items.starterCode:
function isFuture(timestamp, now) {
  return timestamp > Date.now();
}

items.solution:
function isFuture(timestamp, now) {
  return timestamp > now;
}

function ageLabel(createdAt, now) {
  const age = now - createdAt;
  if (age < 10) return "fresh";
  if (age <= 30) return "stale";
  return "expired";
}

